48	/**
49	 * Spring Security configuration for the Connectfolio application.
50	 * <p>
51	 * The configuration supports the following features:
52	 * <ul>
53	 *   <li>Username/password form-based login</li>
54	 *   <li>OAuth2 social login (Google, GitHub, etc.)</li>
55	 *   <li>CSRF protection (disabled for stateless APIs)</li>
56	 *   <li>Rate-limited authentication failure handling</li>
57	 *   <li>Channel security: If SSL is enabled, all requests are forced to HTTPS</li>
58	 *   <li>CORS configuration for REST controllers</li>
59	 * </ul>
60	 *
61	 * The class sits in the “infrastructure” layer of the Clean Architecture setup
62	 * and is kept framework-specific, delegating core authentication business logic
63	 * to {@link DomainUserDetailsService} and other services located in adapter
64	 * packages.
65	 */
66	@Configuration
67	@EnableWebSecurity
68	@EnableMethodSecurity
69	public class SecurityConfig implements EnvironmentAware {
70	
71	    private static final String[] STATIC_RESOURCES = {
72	            "/favicon.ico",
73	            "/assets/**",
74	            "/css/**",
75	            "/js/**",
76	            "/images/**"
77	    };
78	
79	    private Environment env;
