81	    private final DomainUserDetailsService userDetailsService;
82	    private final OAuth2UserService<OAuth2UserRequest, OAuth2User> oAuth2UserService;
83	    private final OAuth2AuthenticationSuccessHandler oAuth2SuccessHandler;
84	    private final LoginAttemptService loginAttemptService;
85	
86	    @Autowired
87	    public SecurityConfig(DomainUserDetailsService userDetailsService,
88	                          CustomOAuth2UserService oAuth2UserService,
89	                          OAuth2AuthenticationSuccessHandler oAuth2SuccessHandler,
90	                          LoginAttemptService loginAttemptService) {
91	        this.userDetailsService = userDetailsService;
92	        this.oAuth2UserService = oAuth2UserService;
93	        this.oAuth2SuccessHandler = oAuth2SuccessHandler;
94	        this.loginAttemptService = loginAttemptService;
95	    }
