97	    /**
98	     * Primary security filter chain that is picked up by Spring Boot (due to the
99	     * absence of {@code WebSecurityConfigurerAdapter} in newer Spring versions).
100	     */
101	    @Bean
102	    @SuppressWarnings("removal")
103	    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
104	
105	        // --- Session & CSRF ---
106	        http
107	            // For classic MVC views we use sessions; REST endpoints are stateless.
108	            .sessionManagement(session -> session
109	                    .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)
110	                    .maximumSessions(3)
111	                    .maxSessionsPreventsLogin(false)
112	                    .expiredSessionStrategy(event ->
113	                            event.getResponse().sendRedirect("/login?expired")))
114	            .csrf(csrf -> csrf
115	                    .ignoringRequestMatchers(new AntPathRequestMatcher("/api/**")));
116	
117	        // --- Channel security (HTTPS enforcement) ---
118	        if (isSslEnabled()) {
119	            http.requiresChannel(channel -> channel.anyRequest().requiresSecure());
120	        }
121	
122	        // --- CORS ---
123	        http.cors(Customizer.withDefaults());
124	
125	        // --- Request authorization ---
126	        http.authorizeHttpRequests(auth -> auth
127	                .requestMatchers(STATIC_RESOURCES).permitAll()
128	                .requestMatchers(HttpMethod.POST, "/api/v1/users").permitAll() // Registration
129	                .requestMatchers("/login",
130	                        "/oauth2/**",
131	                        "/support/**").permitAll()
132	                .requestMatchers("/admin/**").hasRole("ADMIN")
133	                .requestMatchers("/api/**").authenticated()
134	                .anyRequest().permitAll());
135	
136	        // --- Authentication mechanisms ---
137	        http.formLogin(form -> form
138	                .loginPage("/login")
139	                .successForwardUrl("/dashboard")
140	                .failureHandler(rateLimitingFailureHandler())
141	                .permitAll())
142	            .oauth2Login(oauth -> oauth
143	                .loginPage("/login")
144	                .userInfoEndpoint(userInfo -> userInfo.userService(oAuth2UserService))
145	                .successHandler(oAuth2SuccessHandler)
146	                .failureHandler(new SimpleUrlAuthenticationFailureHandler("/login?error")))
147	            .logout(logout -> logout
148	                .logoutUrl("/logout")
149	                .logoutSuccessUrl("/")
150	                .invalidateHttpSession(true)
151	                .deleteCookies("JSESSIONID"));
152	
153	        // --- Exception handling ---
154	        http.exceptionHandling(ex -> ex
155	                .authenticationEntryPoint(restAuthenticationEntryPoint()));
156	
157	        // --- Custom filters (e.g., rate limiting) ---
158	        // register additional filters before UsernamePasswordAuthenticationFilter if necessary
159	        http.addFilterBefore(new ConcurrentSessionFilter(sessionRegistry(),
160	                        new AntPathRequestMatcher("/login?expired")), UsernamePasswordAuthenticationFilter.class);
161	
162	        return http.build();
163	    }
