202	    @Bean
203	    public CorsConfigurationSource corsConfigurationSource() {
204	        CorsConfiguration configuration = new CorsConfiguration();
205	        configuration.setAllowedOriginPatterns(List.of("*"));
206	        configuration.setAllowedMethods(List.of("HEAD", "GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
207	        configuration.setAllowedHeaders(List.of("*"));
208	        configuration.setAllowCredentials(true);
209	        configuration.setMaxAge(3600L);
210	
211	        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
212	        source.registerCorsConfiguration("/api/**", configuration);
213	        return source;
214	    }
