216	    /**
217	     * Handles REST authentication errors by returning 401 instead of redirecting
218	     * to the login page.
219	     */
220	    @Bean
221	    public AuthenticationEntryPoint restAuthenticationEntryPoint() {
222	        return (request, response, authException) -> {
223	            // Only intercept API requests; fallback to default for others
224	            if (request.getRequestURI().startsWith("/api")) {
225	                response.sendError(HttpServletResponse.SC_UNAUTHORIZED, authException.getMessage());
226	            } else {
227	                response.sendRedirect("/login");
228	            }
229	        };
230	    }
