259	    /**
260	     * AuthenticationFailureHandler implementation that leverages
261	     * {@link LoginAttemptService} to throttle brute-force attacks.
262	     */
263	    public static class RateLimitingAuthenticationFailureHandler implements AuthenticationFailureHandler {
264	
265	        private static final String DEFAULT_FAILURE_URL = "/login?error";
266	        private static final int HTTP_TOO_MANY_REQUESTS = 429;
267	
268	        private final LoginAttemptService loginAttemptService;
269	        private final RedirectStrategy redirectStrategy = new DefaultRedirectStrategy();
270	
271	        public RateLimitingAuthenticationFailureHandler(LoginAttemptService loginAttemptService) {
272	            this.loginAttemptService = loginAttemptService;
273	        }
274	
275	        @Override
276	        public void onAuthenticationFailure(HttpServletRequest request,
277	                                            HttpServletResponse response,
278	                                            AuthenticationException exception)
279	                throws IOException, ServletException {
280	
281	            String clientIp = getClientIp(request);
282	            loginAttemptService.recordFailedAttempt(clientIp);
283	
284	            if (loginAttemptService.isBlocked(clientIp)) {
285	                response.sendError(HTTP_TOO_MANY_REQUESTS,
286	                        "Too many failed login attempts. Please try again later.");
287	                return;
288	            }
289	
290	            redirectStrategy.sendRedirect(request, response, DEFAULT_FAILURE_URL);
291	        }
292	
293	        private String getClientIp(HttpServletRequest request) {
294	            String xfHeader = request.getHeader("X-Forwarded-For");
295	            return xfHeader == null ? request.getRemoteAddr() : xfHeader.split(",")[0];
296	        }
297	    }
298	}

